import {progressData,phases,isRunning,phaseWaitSeconds,progressNotice} from './session-progress.js';
import {api,makeEvent,artifact,download,validateSource,fileSourceKind,id} from './session-api.js';
const $=x=>document.getElementById(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let live=null,view=null,drafts=[],busy=false,polling=false,dirty=false;
const labels={created:'已创建',reading:'读取材料',planning:'规划检查',checking:'检查中',awaiting_input:'等待补充',rechecking:'重查中',completed:'本轮结束',cancelled:'已取消',planned:'待执行',running:'执行中',executed:'已执行',blocked:'受阻',failed:'失败',not_executed:'未执行',candidate_issue:'候选问题',no_visible_issue:'未见问题',insufficient_evidence:'证据不足',not_applicable:'不适用',met:'符合',observed_violation:'不符合',open:'未决',no_conflict:'无冲突',needs_clarification:'待澄清',resolved:'已解决',partially_resolved:'部分解决',persists:'仍存在',cannot_determine:'无法判断',manually_excluded:'人工排除',unreviewed:'待审核',confirmed:'已确认',rejected:'已驳回',needs_verification:'待验证'};
const label=x=>labels[x]||x||'未判断';
const message=t=>$('message').textContent=t;
function remember(){let a=[];try{a=JSON.parse(localStorage.getItem('mingjian-session-ids')||'[]');}catch{}if(live){a=[live.session_id,...a.filter(x=>x!==live.session_id)].slice(0,20);localStorage.setItem('mingjian-session-ids',JSON.stringify(a));}$('recent').innerHTML=a.map(x=>`<button data-load="${esc(x)}">${esc(x)}</button>`).join('');}
async function task(fn){if(busy)return;busy=true;message('正在处理…');document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();if($('message').textContent==='正在处理…')message('操作已提交；检查完成情况以会话状态为准。');}catch(e){if(e.status===409&&live){const inputs=[...document.querySelectorAll('#work form')].map(f=>({key:f.dataset.reviewForm||f.dataset.answerForm||f.dataset.recheckForm||f.dataset.conflictForm||f.id,values:[...new FormData(f).entries()]}));try{live=await api.get(live.session_id);view=live;render();for(const f of document.querySelectorAll('#work form')){const key=f.dataset.reviewForm||f.dataset.answerForm||f.dataset.recheckForm||f.dataset.conflictForm||f.id;const saved=inputs.find(x=>x.key===key);if(saved)for(const el of f.elements){if(!el.name)continue;const values=saved.values.filter(([k])=>k===el.name).map(([,v])=>v);if(el.multiple){for(const o of el.options)o.selected=values.includes(o.value);}else if(values.length)el.value=values[0];}}}catch{}message('上下文已更新，请核对最新内容再提交；输入未自动重发。');}else message(e.message);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);lock();}}
function lock(){const historical=view&&live&&view!==live;$('reply').hidden=!!historical;document.querySelectorAll('[data-event], [data-review-form] button,[data-recheck-form] button,[data-answer-form] button,[data-action], [data-conflict-form] button').forEach(b=>b.disabled=busy||historical);const start=document.querySelector('[data-event=resume]');if(start){start.disabled=busy||historical||isRunning(live);start.title=isRunning(live)?'正在执行，请等待进度更新，避免重复调用模型':'';}}
async function send(type,payload){if(view!==live)throw Error('历史报告只读，请刷新当前会话');const actor=$('actor').value.trim();if(!actor)throw Error('请填写审核者 / 操作者');const event=makeEvent(live,type,payload,actor,undefined,$('actorType').value);live=await api.event(live,event);view=live;dirty=false;render();remember();}
function renderDrafts(){$('drafts').innerHTML=drafts.map((s,i)=>`<p>${i+1}. ${esc(s.title||s.filename||s.reference||s.kind)} · ${esc(s.role)} · ${esc(s.version)} <button data-remove="${i}">移除</button></p>`).join('');}
async function readSource(){const f=$('file').files[0],kind=f?fileSourceKind(f):$('kind').value;if(f)$('kind').value=kind;let source={kind,reference:$('reference').value.trim(),title:$('sourceTitle').value.trim(),content:$('content').value,version:$('sourceVersion').value.trim()||'unknown',role:$('role').value,declared_by:$('actor').value.trim()||'unknown'};if(f){if(f.size>(kind==='image'?15:8)*1024*1024)throw Error('文件超出大小限制');if(kind==='image'&&!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('请选择 PNG/JPEG/WebP');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('读取文件失败'));reader.readAsDataURL(f);});source[kind==='image'?'image_base64':'document_base64']=data;source.filename=f.name;}return validateSource(source);}
$('add').onclick=()=>task(async()=>{if(drafts.length>=30)throw Error('最多登记30项材料');drafts.push(await readSource());renderDrafts();$('file').value='';$('reference').value='';$('content').value='';message('材料已加入待提交区，请继续填写评审委托并创建会话。');});
$('drafts').onclick=e=>{if(e.target.dataset.remove!==undefined){drafts.splice(Number(e.target.dataset.remove),1);renderDrafts();}};
$('cap').onclick=()=>task(async()=>{const c=await api.capabilities();$('capText').textContent=` 方法 ${c.methods_version} · ${c.rules} 条判据 · ${c.methods} 项方法；配置不等于已验证`;$('capText').title=JSON.stringify(c,null,2);});
$('create').onsubmit=e=>{e.preventDefault();task(async()=>{if(!drafts.length)throw Error('请先加入至少一项材料');const input={actor:$('actor').value.trim()||'unknown',actor_type:$('actorType').value,purpose:$('purpose').value.trim(),design_purpose:$('designPurpose').value.trim(),target_user:$('targetUser').value.trim(),sources:drafts,provider:$('provider').value,auto_run:$('auto').checked,allow_interaction:$('interact').checked,limits:{max_model_calls:Number($('maxCalls').value),max_seconds:Number($('maxSeconds').value)}};if($('model').value.trim())input.model_name=$('model').value.trim();if(JSON.stringify(input).length>31000000)throw Error('材料总量过大，请减少附件');live=await api.create(input);view=live;drafts=[];renderDrafts();remember();render();if($('intake'))$('intake').open=false;$('work').scrollIntoView({block:'start',behavior:'smooth'});});};
async function restore(sid){live=await api.get(sid.trim());view=live;dirty=false;remember();render();if($('intake'))$('intake').open=false;$('work').scrollIntoView({block:'start'});}
$('restore').onclick=()=>task(()=>restore($('restoreId').value));$('recent').onclick=e=>{if(e.target.dataset.load)task(()=>restore(e.target.dataset.load));};
$('refresh').onclick=()=>task(()=>restore(live.session_id));
$('versions').onchange=()=>task(async()=>{view=$('versions').value==='current'?live:await api.report(live,Number($('versions').value));render();});
$('work').addEventListener('click',e=>{if(e.target.dataset.event)task(()=>send(e.target.dataset.event,{}));if(e.target.dataset.action)task(()=>send('authorize_action',{action_id:e.target.dataset.action,approved:e.target.dataset.approve==='true'}));});
$('reply').onsubmit=e=>{e.preventDefault();task(async()=>{const type=$('eventType').value,text=$('replyText').value.trim();await send(type,{[type==='change_goal'?'purpose':type==='change_scope'?'scope':'text']:text});$('replyText').value='';});};
$('sendSources').onclick=()=>task(async()=>{if(!drafts.length)throw Error('请先登记待提交材料');await send('add_sources',{sources:drafts});drafts=[];renderDrafts();});
$('recheck').onclick=()=>task(async()=>{if(drafts.length!==1)throw Error('请选择恰好一项新版材料加入待提交区');await send('recheck',{updates:[{source_id:$('replaceSource').value,input:drafts[0]}]});drafts=[];renderDrafts();});
const evidenceLinks=(s,ids)=>(ids||[]).map(eid=>`<a href="#ev-${esc(eid)}">${esc(eid)}</a>`).join('、');
function render(){const s=view;if(!s)return;$('work').hidden=false;renderProgress(s);$('sessionTitle').textContent=s.task_summary||s.request.purpose;$('progress').textContent=`${label(s.status)} · 阶段 ${s.active_phase} · 上下文 v${s.context_version} · 报告 v${s.report_version} · ${s.review_mode} · ${s.report_completeness==='complete'?'约定检查处置完整（不是全部通过）':'部分报告'}${view!==live?' · 历史只读':''}`;const selected=view===live?'current':String(s.report_version);$('versions').innerHTML='<option value="current">当前会话</option>'+Array.from({length:live.report_version},(_,i)=>`<option value="${i+1}">报告 v${i+1}</option>`).join('');$('versions').value=selected;
const u=s.material_understanding;$('understanding').innerHTML=`<h2>共享理解与要求</h2><p>评审委托：${esc(s.request.purpose)}</p><p>原始设计目的：${esc(s.request.design_purpose||'未提供，不能用评审委托代替')}</p><p>范围：${esc(s.scope||'待规划')}</p>${[...s.goals,...s.requirements].map(g=>`<div class="session-item"><strong>${esc(g.id)}</strong> ${esc(g.text)} ${g.is_assumption?'（假设）':''}<p>${evidenceLinks(s,g.evidence_ids)}</p></div>`).join('')}<details><summary>专家意见、假设与限制</summary><h3>运行限制</h3>${[...new Set([...(s.run_limitations||[]),...(s.warnings||[])])].map(x=>`<p>${esc(x)}</p>`).join('')||'<p>暂无运行警告</p>'}<h3>假设与待澄清</h3>${[...(s.assumptions||[]),...(u?.unknowns||[])].map(x=>`<p>${esc(x)}</p>`).join('')||'<p>暂无记录</p>'}<details><summary>原始结构化信息（联调）</summary><pre>${esc(JSON.stringify({opinions:u?.opinions,assumptions:s.assumptions,unknowns:u?.unknowns,warnings:s.warnings,limitations:s.run_limitations},null,2))}</pre></details></details>${(u?.conflicts||[]).map(c=>`<form data-conflict-form="${esc(c.conflict_id)}" class="session-item"><h3>材料冲突：${esc(c.topic)}</h3><p>${esc(c.reason)} · ${label(c.status)}</p>${c.source_quotes.map(q=>`<p>${esc(q.quote)} ${evidenceLinks(s,[q.evidence_id])}</p>`).join('')}<label>业务决定<input name="decision" required maxlength="4000"></label><label>理由<input name="reason" required maxlength="3000"></label><label>采纳声明（多选）<select name="accepted" multiple>${c.claim_ids.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>排除声明（多选）<select name="rejected" multiple>${c.claim_ids.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><button>记录决定并重查（调用模型）</button></form>`).join('')}`;
$('materials').innerHTML=`<h2>材料与有效证据</h2>${s.sources.map(x=>`<p>${esc(x.input.title||x.input.reference||x.source_id)} · ${esc(x.acquisition_status)} · ${esc(x.input.role)} · ${esc(x.input.version)}${x.active?'':' · 历史材料'} ${esc(x.error)}</p>`).join('')}${s.evidence.map(e=>`<details id="ev-${esc(e.evidence_id)}" class="session-item"><summary>${esc(e.evidence_id)} · ${esc(e.kind)} · ${e.stale?'过期证据，仅历史':'当前证据'}</summary><p>${esc(e.content)}</p><pre>${esc(JSON.stringify(e.locator,null,2))}</pre>${e.artifact_id?`<a href="${artifact(s,e.artifact_id)}" target="_blank" rel="noopener">查看附件</a> <button data-preview="${esc(e.artifact_id)}" type="button">预览图片</button><div class="preview-box"></div>`:''}${Object.entries(e.overlay_artifact_ids||{}).map(([k,v])=>` <a href="${artifact(s,v)}" target="_blank" rel="noopener">${esc(k)}叠加图</a>`).join('')}</details>`).join('')}`;
$('replaceSource').innerHTML=s.sources.filter(x=>x.active).map(x=>`<option value="${esc(x.source_id)}">${esc(x.input.title||x.input.reference||x.source_id)}</option>`).join('');
$('questions').innerHTML=`<h2>待答问题与操作授权</h2>${s.questions.filter(q=>!q.answered).map(q=>`<form data-answer-form="${esc(q.question_id)}" class="session-item"><h3>${esc(q.text)}</h3><p>${esc(q.reason)} · ${esc(q.kind)} · ${q.blocking?'阻断相关检查':'可继续其他检查'}</p>${q.kind==='authorization'?'<p>请通过下方具体动作批准或拒绝，普通回复不能替代授权。</p>':'<label>回答<textarea name="text" required maxlength="12000"></textarea></label><button>提交回答并重查（调用模型）</button>'}</form>`).join('')||'<p>暂无待答问题。</p>'}${s.actions.filter(a=>a.status==='pending').map(a=>`<div class="session-item"><p>拟执行：${esc(a.kind)} · ${esc(a.target_label||a.url||a.selector)}</p><p>${esc(a.reason)} · 核对对象：${esc(a.observed_target)}</p>${a.target_marker_artifact_id?`<a href="${artifact(s,a.target_marker_artifact_id)}" target="_blank" rel="noopener">查看预执行定位图</a>`:''}<button data-action="${esc(a.action_id)}" data-approve="true">批准此动作</button> <button data-action="${esc(a.action_id)}" data-approve="false">拒绝</button></div>`).join('')}`;
$('findings').innerHTML='<h2>发现与人工审核</h2>'+s.findings.map(f=>`<form class="panel" data-review-form="${esc(f.finding_id)}"><h3>${esc(f.title)} ${f.stale?'（过期，仅历史）':''}</h3><p>${esc(f.kind)} · 模型等级 ${esc(f.severity)} · 人工等级 ${esc(f.human_severity||'未调整')} · ${label(f.review_status)}</p>${['principle','detection','description','suggestion'].map((k,i)=>`<p><strong>${['原则','检测','描述','建议'][i]}</strong>：${esc(f[k])}</p>`).join('')}<p>分级理由：${esc(f.severity_reason)}</p><p>${evidenceLinks(s,f.evidence_ids)}</p><fieldset ${f.stale?'disabled':''}><label>人工状态<select name="review_status">${['unreviewed','confirmed','rejected','needs_verification'].map(x=>`<option value="${x}" ${x===f.review_status?'selected':''}>${label(x)}</option>`).join('')}</select></label><label>人工等级<select name="severity"><option value="">保留模型等级</option>${['critical','high','medium','low'].map(x=>`<option ${x===f.human_severity?'selected':''}>${x}</option>`).join('')}</select></label><label>处理决定<select name="disposition"><option value="">未决定</option>${[['fix','修改'],['accept_risk','接受风险'],['defer','暂缓']].map(([v,t])=>`<option value="${v}" ${v===f.disposition?'selected':''}>${t}</option>`).join('')}</select></label><label>理由<textarea name="reason" maxlength="3000">${esc(f.review_reason)}</textarea></label><button>保存审核（驳回 / 待验证会触发重查）</button></fieldset></form>`).join('');
$('rechecks').innerHTML='<h2>逐问题复审</h2>'+s.rechecks.map(r=>`<form data-recheck-form="${esc(r.recheck_id)}" class="session-item"><p>旧问题 ${esc(r.previous_finding_id)}：${label(r.resolution)} · ${label(r.human_confirmation)}</p><p>${esc(r.reason)}</p><label>复审结果<select name="resolution">${['resolved','partially_resolved','persists','cannot_determine','not_applicable','manually_excluded'].map(x=>`<option value="${x}" ${x===r.resolution?'selected':''}>${label(x)}</option>`).join('')}</select></label><label>新版证据（多选）<select name="evidence_ids" multiple>${s.evidence.filter(e=>!e.stale&&e.context_version===s.context_version).map(e=>`<option value="${esc(e.evidence_id)}" ${r.evidence_ids.includes(e.evidence_id)?'selected':''}>${esc(e.evidence_id+' '+e.content.slice(0,65))}</option>`).join('')}</select></label><label>关联新版发现（多选）<select name="current_finding_ids" multiple>${s.findings.filter(f=>!f.stale).map(f=>`<option value="${esc(f.finding_id)}" ${r.current_finding_ids.includes(f.finding_id)?'selected':''}>${esc(f.title)}</option>`).join('')}</select></label><label>理由<textarea name="reason" required maxlength="3000">${esc(r.reason)}</textarea></label><button>人工确认复审</button></form>`).join('');
$('checks').innerHTML=s.checks.map(c=>`<p>${esc(c.ref)} · ${label(c.execution_status)} · ${label(c.decision)} ${c.stale?'（过期）':''}<br>${esc(c.plan_reason||'')}<br>缺项：${esc((c.evidence_needed||[]).join('；'))}<br>${esc(c.reason)} ${evidenceLinks(s,c.evidence_ids)}</p>`).join('')+(s.screen_reviews||[]).map(x=>`<details><summary>逐屏：${esc(x.node_id||x.evidence_id)} · ${esc(x.status)}</summary><p>${esc(x.summary)}</p>${x.issues.map(i=>`<p>${esc(i.title)}：${esc(i.detection)}；${esc(i.suggestion)}</p>`).join('')}</details>`).join('');
$('exports').innerHTML=[['human','人审稿'],['summary','摘要'],['audit','审计稿'],['json','结构化 JSON'],['zip','完整 ZIP']].map(([k,t])=>`<a class="secondary" href="${download(s,k,view===live?null:s.report_version)}" target="_blank" rel="noopener">${t}</a>`).join('');lock();}
$('work').addEventListener('submit',e=>{const f=e.target;if(f.id==='reply')return;e.preventDefault();const d=new FormData(f);task(async()=>{if(f.dataset.answerForm)await send('reply',{question_id:f.dataset.answerForm,text:d.get('text')});if(f.dataset.reviewForm)await send('review_finding',{finding_id:f.dataset.reviewForm,review_status:d.get('review_status'),reason:d.get('reason'),severity:d.get('severity')||null,disposition:d.get('disposition')||null});if(f.dataset.recheckForm)await send('confirm_recheck',{recheck_id:f.dataset.recheckForm,resolution:d.get('resolution'),reason:d.get('reason'),evidence_ids:d.getAll('evidence_ids'),current_finding_ids:d.getAll('current_finding_ids')});if(f.dataset.conflictForm)await send('resolve_conflict',{conflict_id:f.dataset.conflictForm,decision:d.get('decision'),reason:d.get('reason'),accepted_claim_ids:d.getAll('accepted'),rejected_claim_ids:d.getAll('rejected')});});});
setInterval(async()=>{if(!live||view!==live||busy||polling||document.hidden)return;polling=true;const sid=live.session_id;try{const u=await api.updates(live);if(live.session_id===sid&&u.changed&&u.snapshot){if(dirty||document.activeElement?.closest('#work form')){renderProgress(u.snapshot);message('后台状态已更新；已保留输入，提交时会校验版本。');}else{live=u.snapshot;view=live;render();}}}catch(e){message('更新暂停：'+e.message+'；可手动刷新，输入未丢弃。');}finally{polling=false;}},2500);
remember();

$('work').addEventListener('input',()=>{dirty=true;});

$('materials').addEventListener('click',e=>{const aid=e.target.dataset.preview;if(!aid)return;task(async()=>{const response=await fetch(artifact(view,aid));if(!response.ok)throw Error('附件读取失败');const blob=await response.blob();if(!['image/png','image/jpeg','image/webp'].includes(blob.type))throw Error('该附件不是可预览图片，请使用查看附件');const img=document.createElement('img');img.alt='本轮证据附件';img.className='evidence-image';const url=URL.createObjectURL(blob);img.onload=()=>URL.revokeObjectURL(url);img.onerror=()=>URL.revokeObjectURL(url);img.src=url;e.target.parentElement.querySelector('.preview-box').replaceChildren(img);});});

$('file').addEventListener('change',()=>{const f=$('file').files[0];if(!f)return;try{const kind=fileSourceKind(f);$('kind').value=kind;message(`已选择 ${f.name}，材料类型已切换为${kind==='image'?'图片':'文档'}。链接可留空；请点击“加入待提交材料”。`);}catch(e){message(e.message);}});

function renderProgress(s){let box=$('runProgress');if(!box){box=document.createElement('section');box.id='runProgress';box.className='run-progress';$('progress').after(box);}const p=progressData(s);box.innerHTML=`<h3>${esc(p.title)}</h3><p>当前阶段：${esc(s.active_phase)} · ${esc(phases.find(([id])=>id===s.active_phase)?.[1]||'等待运行')}</p><div class="phase-list">${phases.map(([id,name])=>`<span class="${id===s.active_phase?'phase-current':''}">${id} ${name}</span>`).join('')}</div><label>本轮检查执行覆盖 ${p.total?`${p.done} / ${p.total}（${p.percent}%）`:'尚未建立检查计划'}</label><progress max="${p.total||1}" value="${p.done}" aria-label="本轮检查执行覆盖"></progress><p>已执行 ${p.done} · 执行中 ${p.running} · 待执行 ${p.pending} · 受阻 ${p.blocked} · 失败 ${p.failed}</p><p>材料已取得 ${(s.sources||[]).filter(x=>x.active&&['success','partial'].includes(x.acquisition_status)).length} 项 · 当前有效证据 ${(s.evidence||[]).filter(x=>!x.stale).length} 条 · 已返回并保存的模型调用 ${(s.model_calls||[]).filter(x=>!x.run_id||x.run_id===s.run_id).length} 次</p><p>${esc(progressNotice(s))}</p><p class="muted">模型请求等待中不会立即增加调用计数。覆盖率只统计当前运行的检查项，排除过期记录；不是正确率，也不是整个流程的预计完成百分比。阶段可能循环重查。</p>${p.errors.length?`<div class="run-error" role="alert"><strong>本轮审查中断，请查看具体原因。</strong>${p.errors.map(x=>`<p>${esc(x)}</p>`).join('')}<p>没有发现不代表没有问题；请勿连续点击重跑。请核对上面的具体错误：模型无法连接也可能是请求超时，不能仅据此判断Key或Python配置错误；AttributeError再检查Python环境；若提示原文摘录或输出结构无效，说明模型返回未通过引擎证据校验，应核对材料与模型输出。历史失败记录不会自动变成成功。</p></div>`:''}<p class="muted">后端最近更新：${esc(s.updated_at||'未知')} · 每 2.5 秒检查更新；未提交输入会保留。</p>`;}

setInterval(()=>{if(view)renderProgress(view);},10000);
